import { cva, type VariantProps } from "class-variance-authority"

export const toggleVariants = cva(
  "group/toggle inline-flex items-center justify-center gap-1 rounded-lg text-sm font-medium whitespace-nowrap transition-colors outline-none select-none hover:text-foreground focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 aria-pressed:bg-muted data-[state=on]:bg-muted motion-reduce:transition-none dark:aria-invalid:ring-destructive/40 [&_svg]:fill-current [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        outline: "border border-border bg-transparent hover:bg-muted",
      },
      size: {
        default: "h-8 min-w-8 px-2",
        sm: "h-7 min-w-7 rounded-[min(var(--radius-md),12px)] px-1.5 text-[0.8rem]",
        lg: "h-9 min-w-9 px-2.5",
      },
    },
    defaultVariants: { variant: "default", size: "default" },
  }
)

export type ToggleVariants = VariantProps<typeof toggleVariants>
export type ToggleVariant = NonNullable<ToggleVariants["variant"]>
export type ToggleSize = NonNullable<ToggleVariants["size"]>

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
} from "@angular/core"
import { RdxToggle } from "@radix-ng/primitives/toggle"

import { cn } from "@/lib/utils"

import {
  toggleVariants,
  type ToggleSize,
  type ToggleVariant,
} from "./toggle.variants"

/**
 * Angular port of @force-ui/toggle (radix-force-ui style).
 *
 * Attribute selector — usage:
 *   <button uiToggle [(pressed)]="bold" aria-label="Bold">
 *     <svg>…</svg>
 *   </button>
 */
@Component({
  selector: "[uiToggle]",
  standalone: true,
  template: "<ng-content />",
  changeDetection: ChangeDetectionStrategy.OnPush,
  hostDirectives: [
    {
      directive: RdxToggle,
      inputs: ["pressed", "defaultPressed", "disabled", "value"],
      outputs: ["onPressedChange"],
    },
  ],
  host: {
    "data-slot": "toggle",
    type: "button",
    "[attr.data-variant]": "variant()",
    "[attr.data-size]": "size()",
    "[class]": "classes()",
  },
})
export class ToggleComponent {
  readonly variant = input<ToggleVariant>("default")
  readonly size = input<ToggleSize>("default")
  readonly className = input<string | undefined>(undefined, { alias: "class" })

  protected readonly classes = computed(() =>
    cn(
      toggleVariants({ variant: this.variant(), size: this.size() }),
      this.className()
    )
  )
}
